import { format_date, type Day } from '../parser/date';
import { FIELD, KIND_FIELDS, type TodoEntry, type TodoError } from '../parser/todo';
import { compare_urgency, compute_urgency, hidden_info, urgency_level, type Urgency } from '../urgency';

/** Path of the generated file inside the shared AI folder; one subfolder per plugin. */
export const TASKS_EXPORT_NAME = 'ripe/tasks.md';

/** Settings the export needs. */
export interface TasksExportContext {
	/** Vault path of the todo file. */
	todo_file: string;
	curve_exponent: number;
}

/** Labels of the color levels 0 … 3. */
const LEVEL_LABELS = ['0 new', '1 rising', '2 urgent', '3 critical'];

/** Inline code span that survives backticks in the text. */
function code(text: string): string {
	return text.includes('`') ? `\`\` ${text} \`\`` : `\`${text}\``;
}

/** Text safe for one table cell. */
function cell(text: string): string {
	return text.replace(/\|/g, '\\|').replace(/\s*\n\s*/g, ' ');
}

/** Markdown table from a header and rows. */
function table(header: readonly string[], rows: readonly string[][]): string[] {
	return [
		`| ${header.join(' | ')} |`,
		`|${header.map(() => '---').join('|')}|`,
		...rows.map((row) => `| ${row.map(cell).join(' | ')} |`),
	];
}

/** Title with the detail note, if any; the anchor for finding the line when line numbers shifted. */
function describe_title(entry: TodoEntry): string {
	const { title, note } = entry.todo;
	return note ? `${title || '(no title)'} (note: ${note})` : title || '(no title)';
}

/** Readable problem of a line. */
function describe_error(error: TodoError): string {
	const field = error.field ? code(error.field) : '';
	switch (error.code) {
		case 'missing_field':
			return `missing ${field}`;
		case 'invalid_value':
			return `invalid value of ${field}`;
		case 'conflicting_kinds':
			return `more than one of ${KIND_FIELDS.map(([, key]) => code(key)).join(', ')}`;
	}
}

/** Short explanation of the file format and the urgency model; the tasks themselves stay in the todo file. */
function render_intro(file: string): string[] {
	const f = (key: string): string => code(key);
	return [
		'# Ripe tasks',
		'',
		`Generated by the Obsidian plugin Ripe from ${file}: only the values computed for today.`,
		`Titles, fields and everything else are in ${file}, the only source of truth; change tasks only`,
		`there and never edit this file. It is synced like the notes and may lag behind ${file};`,
		'if that file is newer, the line numbers may have shifted, so match tasks by title.',
		'',
		'## Format of the todo file',
		'',
		'One task per line: `- [ ] Title [field:: value] …`; `- [x]` is a finished one-off task.',
		'Dates `YYYY-MM-DD`, durations a number plus `d`, `w` or `m` (calendar months). The fields decide',
		'when a task is visible ("start") and when it becomes critical:',
		'',
		`- ${f(FIELD.every)} + ${f(FIELD.tolerance)}: start = ${f(FIELD.last_done)} + every (never done: at once),`,
		'  critical = start + tolerance.',
		`- ${f(FIELD.schedule)} (e.g. \`dienstag\`, \`mo, do\`, \`monatlich 1\`): critical = next date, start = critical − ${f(FIELD.lead)}.`,
		`- ${f(FIELD.due)}: start = due − ${f(FIELD.lead)}, critical = due − ${f(FIELD.buffer)}.`,
		`- ${f(FIELD.critical_after)}: start = ${f(FIELD.created)}, critical = created + critical after.`,
		'- none of these: always visible, never critical.',
		'',
		`Also ${f(FIELD.importance)} 1–3, ${f(FIELD.paused_until)} (hidden before that date), ${f(FIELD.done)}, ${f(FIELD.log)}.`,
		'Between start and critical the urgency rises through the levels 0 new, 1 rising, 2 urgent,',
		'3 critical; from the critical day on the task is overdue.',
	];
}

/** Visible open task with its urgency. */
interface VisibleTask {
	entry: TodoEntry;
	urgency: Urgency;
}

/** Computed state of all tasks on `today`. */
function render_state(entries: readonly TodoEntry[], today: Day, ctx: TasksExportContext): string[] {
	const options = { curve_exponent: ctx.curve_exponent };
	const visible: VisibleTask[] = [];
	const hidden: { entry: TodoEntry; until: Day; paused: boolean }[] = [];
	for (const entry of entries) {
		if (entry.todo.done) continue;
		const urgency = compute_urgency(entry.todo, today, options);
		const info = hidden_info(entry.todo, today);
		if (urgency.visible) visible.push({ entry, urgency });
		else if (info) hidden.push({ entry, ...info });
	}
	// Stable sorts: ties keep the file order, so every device produces the same bytes.
	visible.sort(
		(a, b) => compare_urgency(a.urgency, b.urgency) || b.entry.todo.importance - a.entry.todo.importance,
	);
	hidden.sort((a, b) => a.until - b.until);
	const problems = entries.filter((entry) => entry.todo.errors.length > 0);

	const lines = [
		`## State on ${format_date(today)}`,
		'',
		`"Line" is the line number in ${code(ctx.todo_file)}. Finished tasks are left out.`,
		'',
		'### Visible, most urgent first',
		'',
	];
	if (visible.length === 0) lines.push('None.');
	else {
		lines.push(
			...table(
				['Line', 'Task', 'Level', 'Overdue days', 'Critical on'],
				visible.map(({ entry, urgency }) => {
					const level = urgency_level(urgency);
					return [
						String(entry.line_no + 1),
						describe_title(entry),
						level === null ? '–' : (LEVEL_LABELS[level] ?? String(level)),
						urgency.overdue_days > 0 ? String(urgency.overdue_days) : '',
						urgency.window ? format_date(urgency.window.critical) : '',
					];
				}),
			),
		);
	}
	lines.push('', '### Hidden, next first', '');
	if (hidden.length === 0) lines.push('None.');
	else {
		lines.push(
			...table(
				['Line', 'Task', 'Visible from', 'Reason'],
				hidden.map(({ entry, until, paused }) => [
					String(entry.line_no + 1),
					describe_title(entry),
					format_date(until),
					paused ? 'paused' : 'not yet due',
				]),
			),
		);
	}
	if (problems.length > 0) {
		lines.push('', '### Lines with problems', '', 'Treated as tasks without timing until fixed.', '');
		lines.push(
			...table(
				['Line', 'Task', 'Problems'],
				problems.map((entry) => [
					String(entry.line_no + 1),
					describe_title(entry),
					entry.todo.errors.map(describe_error).join('; '),
				]),
			),
		);
	}
	return lines;
}

/**
 * Full content of the AI task file; `entries` null if the todo file does not exist.
 * Deterministic: same tasks, day and settings give the same bytes on every device
 * (no timestamp, no device data, no locale-dependent sorting, `\n` line endings).
 */
export function render_tasks_export(
	entries: readonly TodoEntry[] | null,
	today: Day,
	ctx: TasksExportContext,
): string {
	const state =
		entries === null
			? [`## State on ${format_date(today)}`, '', `The todo file ${code(ctx.todo_file)} does not exist yet.`]
			: render_state(entries, today, ctx);
	return [...render_intro(code(ctx.todo_file)), '', ...state, ''].join('\n');
}
